describe('401 Error Handling - Redirect to Login', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should redirect to login page when API returns 401 Unauthorized', () => {
    // Setup: intercept the API call to simulate 401 response
    cy.intercept('GET', '/api/data', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('unauthorizedData');

    // Attempt to access protected resource
    cy.get('[data-testid="protected-data-button"]').click();

    // Verify redirection to login page
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="login-email"]').should('contain', 'Email');
    cy.get('[data-testid="login-password"]').should('contain', 'Password');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'You are not authorized to access this page');

    // Verify login button is available
    cy.get('[data-testid="login-button"]').should('be.visible');
  });

  it('should handle 401 error with custom error page', () => {
    // Setup: intercept the API call to simulate 401 response
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('unauthorizedProfile');

    // Attempt to access user profile
    cy.get('[data-testid="user-profile-link"]').click();

    // Verify redirection to custom error page
    cy.url().should('include', '/error');
    cy.get('[data-testid="error-page-title"]').should('contain', 'Access Denied');
    cy.get('[data-testid="error-page-description"]').should('contain', 'You are not authorized to view this page');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify login link is available
    cy.get('[data-testid="login-link"]').should('be.visible');
  });
});
